// @generated by the slice schematic 1.1.0 from its spec. Edit in place; reshape via the spec and --force.
import { TestBed } from '@angular/core/testing';
import { BooksViewModel } from './books.view-model';
import { BookService } from '../book/book.service';

describe('BooksViewModel', () => {
  let vm: BooksViewModel;

  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [BooksViewModel] });
    vm = TestBed.inject(BooksViewModel);
  });

  it('lists every record by default', () => {
    expect(vm.filtered().length).toBe(TestBed.inject(BookService).books().length);
  });

  it('filters by the search fields', () => {
    const service = TestBed.inject(BookService);
    const created = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    vm.searchQuery.set('Test title'.toLowerCase());
    expect(vm.filtered().map((item) => item.id)).toContain(created.id);
    vm.searchQuery.set('no record contains this');
    expect(vm.filtered()).toEqual([]);
  });

  it('filters by genre and returns every record when the filter is cleared', () => {
    const service = TestBed.inject(BookService);
    vm.genreFilter.set(vm.genreFilterOptions[1].value);
    expect(vm.filtered().every((item) => item.genre === vm.genreFilter())).toBe(true);
    vm.genreFilter.set('');
    expect(vm.filtered().length).toBe(service.books().length);
  });

  it('orders the list by popularity, descending', () => {
    const values = vm.filtered().map((item) => item.popularity);
    expect(values).toEqual([...values].sort((a, b) => (a - b) * -1));
  });

  it('puts the larger popularity first', () => {
    const service = TestBed.inject(BookService);
    const low = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 9,
      blurb: '',
    });
    const high = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 100,
      blurb: '',
    });
    const ids = vm.filtered().map((item) => item.id);
    expect(ids.indexOf(high.id)).toBeLessThan(ids.indexOf(low.id));
  });

  it('creates a record through save when nothing is being edited', () => {
    const service = TestBed.inject(BookService);
    const before = service.books().length;
    vm.startCreate();
    vm.save({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    expect(service.books().length).toBe(before + 1);
    expect(vm.editing()).toBeNull();
  });

  it('removes a record', () => {
    const service = TestBed.inject(BookService);
    const created = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    vm.remove(created.id);
    expect(service.byId(created.id)).toBeUndefined();
  });

  it('resolves the record being edited once startEdit runs', () => {
    const service = TestBed.inject(BookService);
    const created = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    expect(vm.editingBook()).toBeUndefined();
    vm.startEdit(created.id);
    expect(vm.editingBook()?.id).toBe(created.id);
  });

  it('updates rather than creates when a record is being edited', () => {
    const service = TestBed.inject(BookService);
    const created = service.create({
      title: 'Test title',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    const before = service.books().length;
    vm.startEdit(created.id);
    vm.save({
      title: 'Changed',
      author: 'Test author',
      genre: 'Fiction',
      popularity: 0,
      blurb: '',
    });
    expect(service.books().length).toBe(before);
    expect(service.byId(created.id)?.title).toEqual('Changed');
    expect(vm.editing()).toBeNull();
  });

  it('falls back to a default badge variant for an unlisted availability', () => {
    expect(vm.availabilityVariant('not a listed value')).toBe('secondary');
  });
});
